import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import "bootstrap/dist/css/bootstrap.min.css";

const AdminFProf = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [professor, setProfessor] = useState(null);
  const [cursos, setCursos] = useState([]);
  const [cursoSelecionado, setCursoSelecionado] = useState("");
  const [listaCursos, setListaCursos] = useState([]); // Para os cursos
  const [aluno, setAluno] = useState(null); // Para o aluno

  useEffect(() => {
    const fetchProfessor = async () => {
      try {
        const res = await fetch(`http://localhost:5000/professores/${id}`);
        const data = await res.json();
        if (!data || Object.keys(data).length === 0) {
          throw new Error("Professor não encontrado!");
        }
        setProfessor(data);
        setCursoSelecionado(data.cursoId || "");
      } catch (error) {
        console.error("❌ Erro ao buscar professor:", error);
      }
    };

    const fetchCursos = async () => {
      try {
        const res = await fetch("http://localhost:5000/cursos");
        const data = await res.json();
        if (!data || data.length === 0) {
          throw new Error("Cursos não encontrados!");
        }
        setCursos(data);
        setListaCursos(data); // Preenchendo a lista de cursos
      } catch (error) {
        console.error("❌ Erro ao buscar cursos:", error);
      }
    };

    const fetchAluno = async () => {
      try {
        const resposta = await fetch(`http://localhost:5000/alunos/${id}`);
        if (resposta.ok) {
          const dados = await resposta.json();
          setAluno(dados);
        }
      } catch (error) {
        console.error("Erro na requisição do aluno:", error);
      }
    };

    fetchProfessor();
    fetchCursos();
    fetchAluno();
  }, [id]);

  const atualizarCurso = async () => {
    if (!cursoSelecionado) {
      alert("Por favor, selecione um curso antes de atualizar.");
      return;
    }

    try {
      const res = await fetch(`http://localhost:5000/professores/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ cursoId: cursoSelecionado }),
      });

      if (!res.ok) throw new Error("Erro ao atualizar curso");

      alert("✅ Curso atualizado com sucesso!");
      navigate("/admlistprof");
    } catch (error) {
      console.error("❌ Erro na requisição:", error);
      alert("Erro ao atualizar curso");
    }
  };

  const adicionarCurso = async () => {
    if (!cursoSelecionado) return;

    try {
      const resposta = await fetch(`http://localhost:5000/alunos/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ curso: cursoSelecionado }),
      });

      if (resposta.ok) {
        setAluno({ ...aluno, curso: cursoSelecionado });
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
    }
  };

  if (!professor || !aluno)
    return <p className="text-center mt-4">Carregando...</p>;

  return (
    <div className="container mt-4">
      <h1 className="text-primary text-center">EducaWeb</h1>
      <ul className="nav nav-tabs justify-content-center mt-3">
        <li className="nav-item mx-2">
          <a className="nav-link" href="./admlistcurso">
            Cursos
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link active" href="#">
            Professores
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link" href="./admlistaluno">
            Alunos
          </a>
        </li>
      </ul>

      <h3 className="mt-4">Detalhes do Professor</h3>
      <p>
        <strong>Nome:</strong> {professor.nome}
      </p>
      <p>
        <strong>Email:</strong> {professor.email}
      </p>

      <h4 className="mt-4">Informação do Aluno</h4>
      <p>
        <strong>{aluno.nome}</strong>
      </p>
      <p>{aluno.email}</p>
      <p>{aluno.morada}</p>
      <p>{aluno.contacto}</p>

      <div className="mt-3">
        <label>
          <strong>Curso:</strong>
        </label>
        <select
          className="form-control mt-2"
          value={cursoSelecionado}
          onChange={(e) => setCursoSelecionado(e.target.value)}
        >
          <option value="">Selecione um curso</option>
          {listaCursos.map((curso) => (
            <option key={curso.id} value={curso.id}>
              {curso.nome}
            </option>
          ))}
        </select>
      </div>

      <button className="btn btn-success mt-3" onClick={atualizarCurso}>
        Atualizar Curso
      </button>

      <div className="d-flex justify-content-between mt-3">
        <button
          className="btn btn-danger"
          onClick={() => setCursoSelecionado("")}
        >
          Cancelar
        </button>
        <button className="btn btn-primary" onClick={adicionarCurso}>
          Salvar
        </button>
      </div>

      <button
        className="btn btn-secondary mt-3 mx-2"
        onClick={() => navigate("/admlistprof")}
      >
        Voltar
      </button>
    </div>
  );
};

export default AdminFProf;
